import csv
import io
import re


_COUNT = re.compile(r"(?:[<>]=?|[≤≥=])?\s*[+-]?[0-9]+(?:\.[0-9]+)?")


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    records = list(
        csv.reader(
            io.StringIO(raw_csv, newline=""),
            delimiter=",",
            quotechar='"',
            doublequote=True,
        )
    )

    expected_width = 82
    first_nonblank = None
    first_tabular = None
    header_index = None

    for index, record in enumerate(records):
        populated = [value.strip() for value in record if value.strip()]
        if not populated:
            continue
        if first_nonblank is None:
            first_nonblank = index
        if len(populated) >= 2 and first_tabular is None:
            first_tabular = index

        # The header is label-heavy; the records beneath it mostly contain counts.
        if len(populated) >= expected_width // 2:
            labels = sum(_COUNT.fullmatch(value) is None for value in populated)
            if labels * 2 > len(populated):
                header_index = index
                break

    if header_index is None:
        header_index = first_tabular if first_tabular is not None else first_nonblank
    if header_index is None:
        return {"columns": [], "rows": []}

    columns = records[header_index]
    rows = records[header_index + 1:]
    width = max(len(columns), max(map(len, rows), default=0))

    # Preserve surplus fields in extra columns rather than guessing their meaning.
    used_names = set(columns)
    for position in range(len(columns) + 1, width + 1):
        base = f"extra_{position}"
        name = base
        suffix = 2
        while name in used_names:
            name = f"{base}_{suffix}"
            suffix += 1
        columns.append(name)
        used_names.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
